Ext._define('health.sst.MonitoringHealthManage', {
    extend: 'toolkit.widget.TabPanel',

    getMonitorOccupationalHealthGrid: function (cfgManage, cfg) {
        cfg = core.nullValue(cfg, {});
        if (!this._grid) {
            Ext.applyIf(
                cfg,
                {
                    resource: cfgManage.resourceRestful,
                    region: 'center',
                    gridAutoLoad: true,
                    split: true,
                }
            );
            this._grid = Ext._create('health.sst.MonitorOccupationalHealthGrid', cfg);
        }

        this._grid.getSelectionModel().on({
            scope: this,
            rowselect: function (sm, index, record) {
                this.observer(record.get('pk'), record.get('employee'));
            },
            rowdeselect: function (sm) {
                this.observer(null, null);
            }
        });

        this._grid.getStore().on({
            scope: this,
            load: function () {
                this.observer(null, null);
            }
        });
        return this._grid;
    },

    getExamSstGrid: function (cfgManage, cfg) {
        if (!this._examSstGrid)
            this._examSstGrid = Ext._create('health.sst.ExamSstGrid', {
                title: 'Exames',
                region: 'south',
                height: 300,
                gridAutoLoad: false
            });

        return this._examSstGrid;
    },

    observer: function (monitorOccupationalHealth, employee,  prevent) {
        prevent = core.nullValue(prevent, false);

        if (monitorOccupationalHealth !== undefined) {
            this._monitorOccupationalHealth = monitorOccupationalHealth;
            this._employee = employee;

            !prevent && this.observeMonitorOccupationalHealth();
        }

        return this._monitorOccupationalHealth;
    },

    observeMonitorOccupationalHealth: function () {
        var value = this.observer();

        if (value) {
            this.getExamSstGrid().setParam('monitor_occupational_health', value);
            this.getExamSstGrid().setFilterProperty('monitor_occupational_health', value, 1, false);
            this.getExamSstGrid().setParam('employee', this._employee);
            this.getExamSstGrid().setFilterProperty('employee', this._employee, 2);
            this.getExamSstGrid().enable();
        }
        else{
            this.getExamSstGrid().setParam('monitor_occupational_health', 0);
            this.getExamSstGrid().setParam('employee', 0);
            this.getExamSstGrid().setFilterProperty('monitor_occupational_health', 0, 1, false);
            this.getExamSstGrid().setFilterProperty('employee', 0, 2, false);
            this.getExamSstGrid().getStore().removeAll();
            this.getExamSstGrid().disable();
        }
    },

    constructor: function (cfg) {
        cfg = core.nullValue(cfg, {});
        var _manage = this;

        Ext.applyIf(
            cfg,
            {
                title: 'Monitoração de Saúde do Servidor',
            }
        );

        Ext.apply(
            cfg,
            {
                layout: 'border',
                items: [
                    this.getMonitorOccupationalHealthGrid(cfg, {}),
                    this.getExamSstGrid(cfg, {}),
                ],
            }
        );

        health.sst.MonitoringHealthManage.superclass.constructor.call(this, cfg);
    }
});


